174	func printGreetings(profile *profile.Profile) {
175		fmt.Printf("Memos %s started successfully!\n", profile.Version)
176	
177		if profile.Demo {
178			fmt.Fprint(os.Stderr, "Development mode is enabled\n")
179			if profile.DSN != "" {
180				fmt.Fprintf(os.Stderr, "Database: %s\n", profile.DSN)
181			}
182		}
183	
184		// Server information
185		fmt.Printf("Data directory: %s\n", profile.Data)
186		fmt.Printf("Database driver: %s\n", profile.Driver)
187	
188		// Connection information
189		if len(profile.UNIXSock) == 0 {
190			if len(profile.Addr) == 0 {
191				fmt.Printf("Server running on port %d\n", profile.Port)
192				fmt.Printf("Access your memos at: http://localhost:%d\n", profile.Port)
193			} else {
194				fmt.Printf("Server running on %s:%d\n", profile.Addr, profile.Port)
195				fmt.Printf("Access your memos at: http://%s:%d\n", profile.Addr, profile.Port)
196			}
197		} else {
198			fmt.Printf("Server running on unix socket: %s\n", profile.UNIXSock)
199		}
200	
201		// Access mode is derived from instance_url: set = public, unset = private.
202		accessMode := "private"
203		if profile.AllowAnonymous() {
204			accessMode = "public"
205		}
206		fmt.Printf("Access mode: %s\n", accessMode)
207	
208		fmt.Println()
209		fmt.Printf("Documentation: %s\n", "https://usememos.com")
210		fmt.Printf("Source code: %s\n", "https://github.com/usememos/memos")
211		fmt.Println("\nHappy note-taking!")
212	}
213	
214	func main() {
215		if err := rootCmd.Execute(); err != nil {
216			os.Exit(1)
217		}
218	}

  1	package s3presign
  2	
  3	import (
  4		"context"
  5		"log/slog"
  6		"time"
  7	
  8		"google.golang.org/protobuf/proto"
  9		"google.golang.org/protobuf/types/known/timestamppb"
 10	
 11		"github.com/usememos/memos/internal/storage/s3"
 12		storepb "github.com/usememos/memos/proto/gen/store"
 13		"github.com/usememos/memos/store"
 14	)
 15	
 16	type Runner struct {
 17		Store *store.Store
 18	}
 19	
 20	func NewRunner(store *store.Store) *Runner {
 21		return &Runner{
 22			Store: store,
 23		}
 24	}
 25	
 26	// Schedule runner every 12 hours.
 27	const runnerInterval = time.Hour * 12
 28	
 29	func (r *Runner) Run(ctx context.Context) {
 30		ticker := time.NewTicker(runnerInterval)
 31		defer ticker.Stop()
 32	
 33		for {
 34			select {
 35			case <-ticker.C:
 36				r.RunOnce(ctx)
 37			case <-ctx.Done():
 38				return
 39			}
 40		}
 41	}
 42	
 43	func (r *Runner) RunOnce(ctx context.Context) {
 44		r.CheckAndPresign(ctx)
 45	}
 46	
 47	func (r *Runner) CheckAndPresign(ctx context.Context) {
 48		instanceStorageSetting, err := r.Store.GetInstanceStorageSetting(ctx)
 49		if err != nil {
 50			return
 51		}
 52	
 53		s3StorageType := storepb.AttachmentStorageType_S3
 54		// Limit attachments to a reasonable batch size
 55		const batchSize = 100
 56		offset := 0
 57	
 58		for {
 59			limit := batchSize
 60			attachments, err := r.Store.ListAttachments(ctx, &store.FindAttachment{
 61				GetBlob:     false,
 62				StorageType: &s3StorageType,
 63				Limit:       &limit,
 64				Offset:      &offset,
 65			})
 66			if err != nil {
 67				slog.Error("Failed to list attachments for presigning", "error", err)
 68				return
 69			}
 70	
 71			// Break if no more attachments
 72			if len(attachments) == 0 {
 73				break
 74			}
 75	
 76			// Process batch of attachments
 77			presignCount := 0
 78			for _, attachment := range attachments {
 79				payload := cloneAttachmentPayload(attachment.Payload)
 80				s3ObjectPayload := payload.GetS3Object()
 81				if s3ObjectPayload == nil {
 82					continue
 83				}
 84	
 85				if s3ObjectPayload.LastPresignedTime != nil {
 86					// Skip if the presigned URL is still valid for the next 4 days.
 87					// The expiration time is set to 5 days.
 88					if time.Now().Before(s3ObjectPayload.LastPresignedTime.AsTime().Add(4 * 24 * time.Hour)) {
 89						continue
 90					}
 91				}
 92	
 93				s3Config := instanceStorageSetting.GetS3Config()
 94				if s3ObjectPayload.S3Config != nil {
 95					s3Config = s3ObjectPayload.S3Config
 96				}
 97				if s3Config == nil {
 98					slog.Error("S3 config is not found")
 99					continue
100				}
101	
102				s3Client, err := s3.NewClient(ctx, s3Config)
103				if err != nil {
104					slog.Error("Failed to create S3 client", "error", err)
105					continue
106				}
107	
108				presignURL, err := s3Client.PresignGetObject(ctx, s3ObjectPayload.Key)
109				if err != nil {
110					slog.Error("Failed to presign URL", "error", err, "attachmentID", attachment.ID)
111					continue
112				}
113	
114				s3ObjectPayload.S3Config = s3Config
115				s3ObjectPayload.LastPresignedTime = timestamppb.New(time.Now())
116				if err := r.Store.UpdateAttachment(ctx, &store.UpdateAttachment{
117					ID:        attachment.ID,
118					Reference: &presignURL,
119					Payload:   payload,
120				}); err != nil {
121					slog.Error("Failed to update attachment", "error", err, "attachmentID", attachment.ID)
122					continue
123				}
124				presignCount++
125			}
126	
127			slog.Info("Presigned batch of S3 attachments", "batchSize", len(attachments), "presigned", presignCount)
128	
129			// Move to next batch
130			offset += len(attachments)
131		}
132	}
133	
134	func cloneAttachmentPayload(payload *storepb.AttachmentPayload) *storepb.AttachmentPayload {
135		if payload == nil {
136			return nil
137		}
138		cloned, ok := proto.Clone(payload).(*storepb.AttachmentPayload)
139		if !ok {
140			return nil
141		}
142		return cloned
143	}

 1	package memopayload
 2	
 3	import (
 4		"context"
 5		"log/slog"
 6	
 7		"github.com/pkg/errors"
 8	
 9		"github.com/usememos/memos/internal/markdown"
10		storepb "github.com/usememos/memos/proto/gen/store"
11		"github.com/usememos/memos/store"
12	)
13	
14	type Runner struct {
15		Store           *store.Store
16		MarkdownService markdown.Service
17	}
18	
19	func NewRunner(store *store.Store, markdownService markdown.Service) *Runner {
20		return &Runner{
21			Store:           store,
22			MarkdownService: markdownService,
23		}
24	}
25	
26	// RunOnce rebuilds the payload of all memos.
27	func (r *Runner) RunOnce(ctx context.Context) {
28		// Process memos in batches to avoid loading all memos into memory at once
29		const batchSize = 100
30		offset := 0
31		processed := 0
32	
33		for {
34			limit := batchSize
35			memos, err := r.Store.ListMemos(ctx, &store.FindMemo{
36				Limit:  &limit,
37				Offset: &offset,
38			})
39			if err != nil {
40				slog.Error("failed to list memos", "err", err)
41				return
42			}
43	
44			// Break if no more memos
45			if len(memos) == 0 {
46				break
47			}
48	
49			// Process batch
50			batchSuccessCount := 0
51			for _, memo := range memos {
