   190		done := make(chan struct{})
   191		go func() {
   192			s.wg.Wait()
   193			close(done)
   194		}()
   195	
   196		select {
   197		case <-done:
   198			return nil
   199		case <-ctx.Done():
   200			return ctx.Err()
   201		}
   202	}

